        '<section class="panel pad prospectus-guidance"><h4>Professional calculation rules</h4><div class="grid three"><div><strong>Fixed charges</strong><p>One-off, per-term and academic-year fees can be included directly in calculated totals.</p></div><div><strong>Recurring rates</strong><p>Daily, weekly, monthly and occurrence-based rates remain explicit until calculation units are supplied.</p></div><div><strong>Publication history</strong><p>Every published revision is preserved while the working copy can return to Draft for controlled updates.</p></div></div></section>';
      const openCreate=(rangeCode="")=>{const existing=new Set(snapshots.map(s=>record(s).class_range));openModal("Create School Prospectus","Create an academic-year prospectus for one school class range.",'<form id="prospectusCreateForm" class="form-stack"><div class="form-grid"><label class="field"><span>Academic year</span><select name="academic_year_id" required>'+options(cfg.years,yearId)+'</select></label><label class="field"><span>Class range</span><select name="class_range" required><option value="">Select range</option>'+ranges.filter(([code])=>!existing.has(code)||code===rangeCode).map(([code,label])=>'<option value="'+code+'" '+(code===rangeCode?"selected":"")+'>'+esc(label)+'</option>').join("")+'</select></label><label class="field full"><span>Document title</span><input name="title" value="School Prospectus" maxlength="180" required></label><label class="field"><span>Currency</span><input name="currency_code" value="GHS" maxlength="3" required></label><label class="field"><span>Effective date</span><input type="date" name="effective_date"></label><label class="field full"><span>General note</span><textarea name="general_notes" rows="3"></textarea></label></div><p id="prospectusCreateMessage" class="form-message hidden"></p></form>','<button class="button ghost" id="prospectusCreateCancel">Cancel</button><button class="button primary" id="prospectusCreateSave">Create prospectus</button>');byId("prospectusCreateCancel").onclick=closeModal;byId("prospectusCreateSave").onclick=async()=>{const form=byId("prospectusCreateForm");if(!form.reportValidity())return;const b=byId("prospectusCreateSave");b.disabled=true;try{await certified("save_school_prospectus",{payload:formValues(form)});closeModal();notify("Prospectus created");await renderProspectus();}catch(e){showMessage("prospectusCreateMessage",friendly(e));}finally{b.disabled=false;}};};
