      const form=byId("delegationForm"),classSelect=form.elements.class_id,subjectSelect=form.elements.subject_id,typeSelect=form.elements.delegation_type,delegateSelect=form.elements.delegate_user_id;
      const syncSubjects=()=>{const rowsForClass=subjects.filter(s=>!classSelect.value||String(s.class_id)===String(classSelect.value));subjectSelect.innerHTML='<option value="">All assigned subjects</option>'+rowsForClass.map(s=>'<option value="'+esc(s.subject_id||s.id)+'">'+esc(s.subject_name||s.name||"Subject")+'</option>').join("");};
