      byId("content").querySelectorAll("[data-id-mode]").forEach(b=>b.onclick=()=>{local.idCards.mode=b.dataset.idMode;renderIdCards();});byId("idCardYear").onchange=()=>{local.idCards.yearId=byId("idCardYear").value;renderIdCards();};byId("idCardClass")?.addEventListener("change",()=>{local.idCards.classId=byId("idCardClass").value;renderIdCards();});byId("idCardStatus").onchange=()=>{local.idCards.status=byId("idCardStatus").value;renderIdCards();};
      const cardById=id=>cards.find(card=>String(card.id)===String(id));
      const printableCardHtml=card=>'<article style="width:85.6mm;height:53.98mm;border:1px solid #d7deea;border-radius:4mm;padding:5mm;box-sizing:border-box;display:grid;grid-template-columns:1fr auto;gap:4mm;break-inside:avoid;background:#fff"><div><h3 style="margin:0 0 2mm;color:#123a79;font-size:13pt">'+esc(window.EdusentiaShell?.state?.boot?.tenant?.name||"School")+'</h3><div style="font-weight:800;font-size:15pt">'+esc(card.staff_name||card.student_name||card.full_name||"")+'</div><div style="font-size:9pt;margin-top:2mm">'+esc(card.staff_no||card.admission_no||"")+'</div><div style="font-size:9pt">'+esc(mode==="staff"?(card.role_label||title(card.staff_type)):(card.class_name||""))+'</div><div style="font-size:8pt;margin-top:3mm">Card: '+esc(card.card_number||"—")+' • Expires '+formatDate(card.expires_on)+'</div></div><div style="text-align:center;font-size:8pt;width:27mm"><div style="border:1px solid #d8dde6;border-radius:2mm;height:30mm;display:grid;place-items:center;padding:1mm">QR verification<br>'+esc(String(card.verification_token||card.card_number||"").slice(0,18))+'</div><b>'+esc(title(card.status||"active"))+'</b></div></article>';
      const openPrint=(selected=cards)=>{if(!selected.length){notify("No ID cards to print","Adjust the filters or generate cards first.","warning");return;}const w=window.open("","_blank","noopener,noreferrer");if(!w){notify("Printable sheet blocked","Allow pop-ups for this school workspace and try again.","error");return;}w.document.write('<!doctype html><html><head><title>ID Cards</title><style>@page{size:A4;margin:10mm}body{font-family:Arial,sans-serif;margin:0}.sheet{display:grid;grid-template-columns:repeat(2,85.6mm);gap:7mm 8mm;justify-content:center}@media print{button{display:none}}</style></head><body><div class="sheet">'+selected.map(printableCardHtml).join("")+'</div><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>');w.document.close();};
